<x-app-layout><x-slot name="header"><h2>{{ $project->name }}</h2></x-slot><main class="max-w-6xl mx-auto p-6 space-y-5"><p>Health: {{ $health }} · Progress: {{ $progress }}% · Overdue: {{ $overdue }} · Spent: {{ number_format($spent,2) }}</p><a href="{{ route('projects.export',$project) }}">Download CSV report</a><form method="get"><input name="q" value="{{ request('q') }}" placeholder="Search"><select name="status"><option value="">All</option>@foreach(['todo','in_progress','review','done'] as $s)<option>{{ $s }}</option>@endforeach</select><button>Filter</button></form><section><h3>Project members</h3>@foreach($members as $member)<p>{{ $member->name }} · {{ $member->pivot->role }}</p>@endforeach<form method="post" action="{{ route('projects.members.store',$project) }}">@csrf<input name="email" type="email" required placeholder="Registered email"><select name="role"><option>member</option><option>manager</option></select><button>Add member</button></form></section><section><h3>Tasks</h3>@forelse($tasks as $task)<p>{{ $task->title }} · {{ ['todo'=>'To do','in_progress'=>'In progress','done'=>'Done'][$task->status] ?? $task->status }}</p>@empty<p>No tasks yet</p>@endforelse<form method="post" action="{{ route('projects.tasks.store',$project) }}">@csrf<input name="title" required><select name="priority"><option>low</option><option selected>medium</option><option>high</option></select><input type="hidden" name="status" value="todo"><button>Add task</button></form></section><section><h3>Milestones</h3>@foreach($milestones as $m)<p>{{ $m->name }} · {{ $m->due_date?->format('M j, Y') }}</p>@endforeach<form method="post" action="{{ route('projects.milestones.store',$project) }}">@csrf<input name="name" required><input type="date" name="due_date"><button>Add</button></form></section><section><h3>Risks and issues</h3>@foreach($risks as $risk)<p>{{ $risk->kind }}: {{ $risk->title }} ({{ $risk->severity }})</p>@endforeach<form method="post" action="{{ route('projects.risks.store',$project) }}">@csrf<select name="kind"><option>risk</option><option>issue</option></select><input name="title" required><input name="description" required><select name="severity"><option>low</option><option selected>medium</option><option>high</option></select><button>Record</button></form></section><section><h3>Budget and expenses</h3><p>{{ $project->budget===null?'No budget set':'Budget '.number_format((float)$project->budget,2) }}</p>@if($project->budget!==null)<form method="post" action="{{ route('projects.expenses.store',$project) }}">@csrf<input name="description" required><input name="amount" type="number" min=".01" step=".01" required><input name="spent_at" type="date" required><button>Record expense</button></form>@endif</section><section><h3>Activity</h3>@foreach($activities as $a)<p>{{ $a->event }} · {{ $a->created_at }}</p>@endforeach</section></main></x-app-layout>
